const dialog=node('dialog','cs-dialog');dialog.setAttribute('aria-label','تغییر برنامه کلاس');document.body.append(dialog);
const can=()=>uid&&['admin','student'].includes(role),norm=s=>String(s||'').replace(/[\s\u200c]/g,'').replace(/ي/g,'ی').replace(/ك/g,'ک').toLowerCase(),name=s=>s.first_name+' '+s.last_name,date=s=>AcademyDates.show(String(s).slice(0,10)),teacherName=id=>state?.teachers.find(t=>t.id===id)?.name||'—';
const schedule=s=>s?`استاد ${teacherName(s.teacher_id)} · ${days[s.weekday]} · ${s.class_time.slice(0,5)}`:'—',labels={pending:'در انتظار بررسی',approved:'تأیید و اعمال‌شده',rejected:'ردشده',superseded:'برنامه مستقیماً تغییر کرده'};
