views.schedule_changes=()=>title('برنامه‌ای هماهنگ‌تر',admin?'ویرایش مستقیم کلاس و بررسی درخواست‌های هنرجویان':'درخواست تغییر روز، ساعت یا استاد؛ جداگانه برای هر کلاس')+'<div id="class-change-root"></div>';
